package edu.alliance.medislot.servlet;import com.fasterxml.jackson.databind.*;import jakarta.servlet.http.*;import java.io.*;import java.util.*;public abstract class JsonServlet extends HttpServlet{protected static final ObjectMapper JSON=new ObjectMapper();protected JsonNode body(HttpServletRequest r)throws IOException{return JSON.readTree(r.getInputStream());}protected void send(HttpServletResponse r,int code,Object o)throws IOException{r.setStatus(code);r.setContentType("application/json;charset=UTF-8");JSON.writeValue(r.getOutputStream(),o);}protected void error(HttpServletResponse r,int code,String m)throws IOException{send(r,code,Map.of("error",m));}}